        public static void AddHead(RigDef rig, string id)
        {
            string style = Hairstyles.Resolve(id);
            rig.hairCentre = KageModel.P(862, 150);
            rig.parts.Add(new PartDef
            {
                name = "Hair_" + style, bone = B.Head, order = 84, role = PartRole.Hair, soft = SoftKind.Hair,
                hairTrailLength = style == "long_flowing" ? 0.82f : 0f,
                polys = new List<(Vector2[], Color)>(Styles[style]), rim = false,
            });
            // The original eye stays rigid while the locks move in the rig's wind field.
            foreach (var plane in KageSvg.Hair)
            {
                if (plane.role != 6) continue;
                var eye = new Vector2[plane.xy.Length / 2];
                for (int i = 0; i < eye.Length; i++) eye[i] = KageModel.P(plane.xy[2 * i], plane.xy[2 * i + 1]);
                rig.parts.Add(new PartDef { name = "Eye", bone = B.Head, order = 96, role = PartRole.Eye,
                    pts = eye, color = Palette.Eye, rim = false, glow = 3.6f });
            }
        }
    }
